insert into public.irritants (id,position,titre,court,signal,color,note,traitement,reponse,demo,proposition,pourquoi) values
('arrivee',0,'Arrivées mal préparées : annonces incomplètes, demandes au support trop tardives','Arrivées mal préparées','Arrivée mal préparée','#e11d48',11,'Assister','agent',true,'Agent d''intégration : à chaque annonce d''arrivée, il compare l''annonce à la checklist, liste ce qui manque, calcule le rétro-planning (poste 10 jours ouvrés, habilitation 15, badge 3) et prépare les messages au manager, à l''informatique et aux services généraux.','Lire une annonce écrite librement, repérer ce qui manque selon le profil (une habilitation pour un consultant cybersécurité) et rédiger trois messages adaptés demande compréhension et rédaction. Un formulaire aide, mais les managers continueront d''écrire par mail (mails 1, 4, 14, 21). L''agent prépare, la RH envoie.'),
('doc',1,'Documentation dispersée : plusieurs versions, liens inaccessibles, règles contradictoires','Documentation dispersée','Version incertaine','#7c3aed',10,'Simplifier (sans agent)','document',false,'Pas d''agent. Une page de référence unique, une seule version par document, lisible avant l''arrivée. La RH archive les anciennes versions.','Le problème n''est pas de trouver le document : il en existe trois. Un agent de recherche documentaire masquerait le désordre au lieu de le supprimer.'),
('questions',2,'Mêmes questions à chaque arrivée (télétravail, mutuelle, premier jour)','Questions récurrentes','Question récurrente','#0ea5e9',7,'Simplifier','document',false,'Une FAQ d''accueil jointe au mail de bienvenue. L''assistant en propose le contenu à partir des questions reçues, la RH valide.','Les questions sont prévisibles et les réponses stables : un document suffit. L''IA sert une seule fois, pour rédiger la FAQ.'),
('actions',3,'Actions de réunion jamais fermées, comptes rendus diffusés tard et peu lus','Actions jamais fermées','Action reportée','#10b981',7,'Simplifier','document',false,'Un modèle de compte rendu avec un tableau d''actions (responsable, échéance, statut) repris en tête du compte rendu suivant. En option, l''assistant prépare le brouillon à partir de notes tapées, jamais d''un enregistrement.','Ce qui manque, c''est un suivi des actions, pas une rédaction plus rapide. Visios et enregistrements sont exclus par Scalian.'),
('boucle',4,'Services généraux hors de la boucle des arrivées','Acteur oublié','Acteur oublié','#f59e0b',6,'Simplifier','reglage',false,'Ajouter les services généraux à la liste de diffusion des annonces d''arrivée.','Un réglage de messagerie suffit : aucune IA n''est nécessaire pour mettre quelqu''un en copie.'),
('pieces',5,'Pièces renvoyées faute d''accusé de réception','Pièces renvoyées','Renvoi','#64748b',6,'Automatiser','automatisation',false,'Une réponse automatique à la réception d''un dossier, avec la liste des pièces attendues. L''assistant ne lit jamais le contenu des pièces.','Accuser réception est une règle fixe. Les pièces contiennent des données personnelles : l''IA n''a rien à y faire.');
insert into public.irritant_status (irritant_id) select id from public.irritants;
insert into public.events (position,jour,src,ref,de_nom,titre,texte,irr,conf,aparte,live) values
(0,'J1','mail','Mail 1','Olivier Lambert, manager','Arrivée Hugo Lefèvre','Hugo arrive le lundi 15 comme consultant test logiciel. « Vous pouvez lancer le nécessaire ? »',ARRAY['arrivee']::text[],false,null,false),
(1,'J2','cr','CR-1',null,'Point hebdo intégration','« Arrivées à venir : aucune signalée. » Délai poste rappelé : 10 jours ouvrés. Mise à jour du livret d''accueil : reportée, prévue depuis septembre. Accès aux documents avant l''arrivée : sans responsable.',ARRAY['arrivee','doc','actions']::text[],false,null,false),
(2,'J2','mail','Mail 2','Camille Rousseau, RH','Bienvenue chez nous !','Liste des pièces à retourner, et lien vers le livret d''accueil : Livret_accueil_2024.pdf.',ARRAY['doc']::text[],false,null,false),
(3,'J3','mail','Mail 3','Hugo Lefèvre, futur employé','RE: Bienvenue chez nous !','« Le livret indique un jour de télétravail, en entretien on m''a parlé de deux. » Ne trouve pas le formulaire de mutuelle.',ARRAY['doc','questions']::text[],false,null,false),
(4,'J4','mail','Mail 4','Olivier Lambert, manager','Encore une arrivée le 15','Sarah arrive aussi le 15. « Il lui faudra un PC, je ne sais pas trop à qui faire la demande. »',ARRAY['arrivee']::text[],false,null,false),
(5,'J5','mail','Mail 5','Sarah Benmoussa, future employée','Lien mutuelle','Le lien vers le formulaire de mutuelle affiche « accès refusé ».',ARRAY['doc','questions']::text[],false,null,false),
(6,'J8','mail','Mail 6','Camille Rousseau, RH','2 postes pour lundi 15','Demande à l''informatique deux PC et les comptes, 5 jours ouvrés avant l''arrivée.',ARRAY['arrivee']::text[],false,null,false),
(7,'J9','cr','CR-2',null,'Point hebdo intégration','Postes commandés, livraison deux jours après l''arrivée. Formulaires de compte en attente. Livret : reporté. Checklist commune : « à lancer ». Services généraux excusés pour la 2e fois.',ARRAY['actions','boucle','arrivee']::text[],false,null,false),
(8,'J9','mail','Mail 7','Marc Dubois, informatique','RE: 2 postes pour lundi 15','« Le délai, c''est 10 jours ouvrés. » Livraison le 17 au plus tôt ; formulaire de création de compte manquant pour les deux.',ARRAY['arrivee']::text[],false,null,false),
(9,'J9','mail','Mail 8','Hugo Lefèvre, futur employé','Mes documents (2e envoi)','Renvoie ses documents : pas de confirmation du premier envoi.',ARRAY['pieces']::text[],false,null,false),
(10,'J10','mail','Mail 9','Camille Rousseau, RH','Formulaire création de compte','« Je crois que c''est la bonne version, il y en a deux sur le SharePoint. »',ARRAY['doc']::text[],false,null,false),
(11,'J11','mail','Mail 10','Sarah Benmoussa, future employée','Lundi : où et à quelle heure ?','Pas de programme reçu : agence ou client ? À quelle heure ?',ARRAY['questions']::text[],false,null,false),
(12,'J12','mail','Mail 11','Sandrine Petit, services généraux','Arrivées de lundi ?','« J''apprends à la machine à café que deux personnes arrivent lundi. » Badges non commandés.',ARRAY['boucle','arrivee']::text[],false,null,false),
(13,'J15','mail','Mail 12','Olivier Lambert, manager','Premier jour sans PC','Les deux arrivants passent la journée sans PC. « Est-ce qu''on peut éviter ça la prochaine fois ? »',ARRAY['arrivee']::text[],false,null,false),
(14,'J16','mail','Mail 13','Hugo Lefèvre, nouvel arrivant','Quel livret d''accueil ?','Trois livrets dans le dossier Accueil (2024, 2025_v2, 2025 FINAL) : « Lequel fait foi ? » Note de frais introuvable.',ARRAY['doc']::text[],false,null,false),
(15,'J16','mail','Mail 14','Julien Mercier, HRBP','Arrivée Antoine Roche lundi 22','Consultant sécurité, arrive dans 6 jours. « Tu as une checklist d''arrivée à jour ? Je n''ai que celle de 2023. »',ARRAY['arrivee','doc']::text[],false,null,false),
(16,'J17','mail','Mail 15','Antoine Roche, futur employé','Quelques questions avant lundi','Télétravail ? Mutuelle ? Heure d''arrivée lundi ? Les mêmes questions que les deux arrivants précédents.',ARRAY['questions']::text[],false,null,false),
(17,'J18','mail','Mail 16','Marc Dubois, informatique','Habilitation Antoine','Une habilitation cybersécurité se demande 15 jours ouvrés avant. « Personne ne me l''a demandée. »',ARRAY['arrivee']::text[],false,null,false),
(18,'J18','mail','Mail 17','Expéditeur masqué','Demande de rendez-vous confidentiel','Contenu non affiché.',ARRAY[]::text[],true,'Classé confidentiel sur son objet : contenu non analysé, non résumé, non inscrit au registre. Transmis tel quel au HRBP.',false),
(19,'J19','mail','Mail 18','Mutuelle','Votre lettre d''information de novembre','Newsletter.',ARRAY[]::text[],false,'Bruit : ignoré.',false),
(20,'J19','mail','Mail 19','Comité d''agence','Afterwork de fin d''année','Invitation.',ARRAY[]::text[],false,'Bruit : ignoré.',false),
(21,'J19','cr','CR-3',null,'Point hebdo intégration (réunion J16, diffusé J19)','Deux arrivants sans PC le premier jour. Chacun tient sa liste : tableur RH, outil informatique, cahier des services généraux. Livret : 3e report. Checklist commune : pas commencée.',ARRAY['actions','boucle','doc']::text[],false,null,false),
(22,'J19','cr','CR-4',null,'Comité RH mensuel','Premiers jours difficiles remontés par deux managers. Télétravail : l''accord 2025 dit deux jours, le livret un seul. Checklist commune déjà décidée au comité précédent. Les managers ne lisent pas les comptes rendus des points hebdo. Sujet reporté.',ARRAY['actions','doc','arrivee']::text[],false,null,false),
(23,'J22','mail','Mail 20','Karine Dumas, manager','Arrivée d''Antoine','PC de secours prêté, mais pas d''accès à l''outil des temps ni d''habilitation avant deux semaines : impossible de le positionner sur sa mission.',ARRAY['arrivee']::text[],false,null,false),
(1000,'Live','mail','Mail 21','Isabelle Moreau, manager','Arrivée Lucas Fabre lundi prochain','« Lucas Fabre nous rejoint lundi prochain comme consultant data. Merci de faire le nécessaire ! »',ARRAY['arrivee']::text[],false,null,true);
insert into public.arrivees (id,nom,poste) values ('lucas-fabre','Lucas Fabre','Consultant data');
insert into public.brouillons (id,position,arrivee_id,destinataire,objet,corps) values
('manager',0,'lucas-fabre','Isabelle Moreau, manager','Arrivée de Lucas Fabre : 3 informations manquantes','Bonjour Isabelle, pour préparer l''arrivée de Lucas lundi, il nous manque le lieu du premier jour (agence ou client), le matériel nécessaire et les accès particuliers éventuels. Le délai habituel d''un poste (10 jours ouvrés) est dépassé : nous demandons un PC de secours. Vous pouvez aussi compléter l''annonce dans ACIA. Camille'),
('it',1,'lucas-fabre','Marc Dubois, informatique','Arrivée lundi : PC de secours et comptes','Bonjour Marc, Lucas Fabre, consultant data, arrive lundi dans la BU Data. Le délai poste est dépassé : un PC de secours est-il possible ? Le formulaire de création de compte, signé par Isabelle Moreau, suit. Camille'),
('sg',2,'lucas-fabre','Sandrine Petit, services généraux','Arrivée lundi : badge et place','Bonjour Sandrine, Lucas Fabre arrive lundi : badge et place à prévoir. Le lieu du premier jour est en cours de confirmation avec sa manager. Camille');
insert into public.ref_content (key,value) values
('sources','{"mail":{"label":"Boîte RH","cls":"b-violet"},"cr":{"label":"Compte rendu","cls":"b-sky"}}'::jsonb),
('reponses','[{"id":"reglage","label":"Réglage d''un outil existant","color":"#64748b"},{"id":"document","label":"Document ou modèle unique","color":"#059669"},{"id":"automatisation","label":"Automatisation simple","color":"#0284c7"},{"id":"workflow","label":"Workflow sans IA","color":"#0d9488"},{"id":"agent","label":"Nouvel agent IA","color":"#7c3aed"}]'::jsonb),
('contre','{"arrivee":{"objection":"Un formulaire d''annonce obligatoire suffirait peut-être, sans agent.","verif":"Les 4 annonces arrivent par mail, écrites librement, par 4 personnes différentes (mails 1, 4, 14, 21). Le délai de 10 jours est connu de tous (CR-1, mail 7) et pourtant dépassé : le problème est autant le calcul des échéances que la saisie.","conclusion":"Irritant maintenu, confiance moyenne. Recommandation : un formulaire (sans IA) ET l''agent pour les annonces qui continueront d''arriver par mail. À confirmer avec la RH.","ok":true},"doc":{"objection":"Un agent de recherche documentaire aiderait-il les arrivants à trouver le bon livret ?","verif":"Le problème n''est pas de trouver : il existe 3 livrets, 2 formulaires de compte et 2 textes sur le télétravail qui se contredisent (mails 3, 9, 13, CR-4).","conclusion":"Pas d''agent. Une page de référence unique, une version par document. Un agent masquerait le désordre au lieu de le supprimer.","ok":true}}'::jsonb),
('questions_contre','["Le mail est-il vraiment ce que la détection affirme (une annonce, une question, un renvoi) ?","L''information a-t-elle pu circuler ailleurs (téléphone, réunion) ?","L''irritant tient-il au processus, ou à un cas isolé ?","Les sources citées disent-elles bien ce que la détection affirme ?","La réponse proposée est-elle la plus simple ? Un document ou un réglage suffirait-il ?"]'::jsonb),
('spec_integration','[["Irritant détecté","Les arrivées sont mal préparées : 3 annonces incomplètes sur 3, demandes au support parties après les délais connus, 3 arrivants sur 3 sans poste ou sans accès complet le premier jour. Sources : mails 1, 4, 6, 7, 11, 12, 14, 16, 20 ; CR-1 à CR-4. Confiance moyenne après contre-analyse. Interprétation des signaux, pas une cause prouvée. Données fictives."],["Besoin métier","« Quand un manager m''annonce une arrivée, je veux savoir tout de suite ce qui manque et ce qui est déjà en retard, et avoir les messages prêts. » (administration du personnel)"],["Utilisateurs","L''administration du personnel (valide et envoie), le manager (reçoit la demande d''informations), l''informatique et les services généraux (reçoivent les demandes), le HRBP (propriétaire du processus)."],["Entrées","Mails de la boîte RH qui annoncent une arrivée ; checklist d''intégration de référence et délais par étape (Notion)."],["Sorties","Une fiche d''arrivée dans Notion (étapes, échéances, statut) ; 3 brouillons : au manager (informations manquantes), à l''informatique (poste, comptes, habilitation), aux services généraux (badge, place) ; une alerte si un délai est déjà dépassé, avec une solution de repli."],["Workflow","1. Un mail annonce une arrivée. 2. L''agent extrait date, poste, manager, lieu, matériel, accès. 3. Il compare à la checklist et liste ce qui manque. 4. Il calcule le rétro-planning et repère les délais dépassés. 5. Il crée la fiche d''arrivée et prépare les 3 brouillons. 6. La RH relit, modifie, envoie. 7. Cinq jours avant l''arrivée, l''agent signale les étapes non faites."],["Niveau d''autonomie","Préparer. L''agent n''envoie rien : une mauvaise date ou un message mal formulé peut coûter un premier jour. Le passage à « agir » (envoi automatique des demandes standard à l''informatique) n''est envisageable qu''après une période de mesure, sur décision du HRBP."],["Permissions et risques","Lecture de la boîte RH ; écriture de la fiche d''arrivée et des brouillons. Jamais : lire les pièces administratives, lire un mail classé confidentiel, envoyer un mail, évaluer une personne. Risque : données personnelles du futur employé. Parade : l''agent ne traite que l''annonce (nom, date, poste), jamais le dossier. Risque : faux positif. Parade : la RH valide chaque fiche."],["Agent proposé","Nouvel agent, branché sur la boîte RH (MCP Thunderbird) et sur Notion (checklist, fiches d''arrivée). En complément, sans IA : un formulaire d''annonce pour les managers qui préfèrent l''utiliser."],["Critères d''acceptation","Sur le jeu de données : les 4 annonces reconnues (mails 1, 4, 14, 21) ; les informations manquantes listées sans erreur ; le délai dépassé signalé pour le mail 21 ; l''habilitation de l''arrivant cybersécurité repérée dès le mail 14 ; le mail 17 jamais analysé ; aucun mail envoyé."],["Gain attendu et indicateur","Indicateur principal : part des arrivants avec poste et accès prêts le premier jour. Secondaire : nombre de mails échangés par arrivée avant le premier jour. Valeurs : à mesurer, avant et après."]]'::jsonb),
('gen_steps','["Lecture de l''irritant validé et de ses sources","Application du modèle en 11 rubriques","Choix du niveau d''autonomie le plus bas qui suffit","Vérification : validation humaine, aucun envoi, aucun chiffre inventé, aucune donnée individuelle"]'::jsonb),
('prompt_gen','"Tu es analyste métier RH. À partir de l''irritant ci-dessous et de ses sources, rédige une spécification selon ce modèle : Irritant détecté, Besoin métier, Utilisateurs, Entrées, Sorties, Workflow, Niveau d''autonomie, Permissions et risques, Agent proposé, Critères d''acceptation, Gain attendu et indicateur.\n\nRègles :\n- Propose d''abord la réponse la plus simple : un réglage, un document ou un workflow sans IA avant un agent.\n- Le workflow contient toujours une étape de validation humaine.\n- Rien n''est envoyé sans validation.\n- Aucune donnée individuelle : l''irritant décrit une étape du processus, jamais une personne.\n- Les mails confidentiels et les pièces administratives ne sont jamais lus.\n- N''invente aucun chiffre : si un gain n''est pas chiffrable, écris-le.\n- Cite les sources (numéros de mails, comptes rendus)."'::jsonb),
('agent_steps','[{"label":"Lecture du mail 21","detail":"« Lucas Fabre nous rejoint lundi prochain comme consultant data. Merci de faire le nécessaire ! »","outil":"MCP Thunderbird"},{"label":"Reconnaissance d''une annonce d''arrivée","detail":"Nom, poste (consultant data), date (lundi prochain), manager (expéditrice).","outil":"Claude"},{"label":"Comparaison avec la checklist","detail":"Manquent 3 informations sur 6 : lieu du premier jour, matériel, accès particuliers.","outil":"MCP Notion"},{"label":"Calcul du rétro-planning","detail":"Poste : 10 jours ouvrés, délai déjà dépassé. Badge : 3 jours, possible si demandé aujourd''hui. Repli proposé : PC de secours.","outil":"Claude"},{"label":"Rapprochement avec l''historique","detail":"Même schéma pour les 3 arrivées précédentes, quel que soit le manager : c''est le processus qui est en cause, pas une personne.","outil":"Claude"},{"label":"Contre-analyse","detail":"Les informations ont-elles été données par téléphone ? Aucune trace écrite : l''agent pose la question au lieu de supposer.","outil":"Claude"},{"label":"Fiche d''arrivée et 3 brouillons","detail":"Fiche créée dans Notion. Brouillons : à la manager, à l''informatique, aux services généraux.","outil":"MCP Notion"},{"label":"La RH relit et envoie","detail":"Camille valide, modifie ou ignore. L''agent n''envoie rien lui-même.","outil":"Humain","human":true}]'::jsonb),
('roles','[{"id":"collab","nom":"Camille","role":"Administration du personnel","persona":"Collaborateur","tabs":[["arrivees","Arrivées à préparer"],["registre","Ce que l''assistant repère dans mon activité"]]},{"id":"manager","nom":"Isabelle","role":"Manager BU Data","persona":"Manager","tabs":[["mesarrivees","Mes arrivées"],["equipe","Irritants qui touchent mon équipe"]]},{"id":"hrbp","nom":"Julien","role":"HRBP","persona":"HRBP","tabs":[["registre","Registre RH"],["orienter","Valider et orienter"],["spec","Spécifications"],["suivre","Suivi des réponses"],["detection","Détection IA"]]},{"id":"dir","nom":"Direction","role":"Direction d''agence","persona":"Dirigeants","tabs":[["tableau","Tableau de bord"]]},{"id":"futur","nom":"Lucas","role":"Futur employé","persona":"Futur employé","tabs":[["futur","Ce qu''il reçoit"]]}]'::jsonb),
('arrivees_passees','[{"nom":"Hugo Lefèvre","poste":"Consultant test logiciel","date":"J15","etat":"Premier jour sans poste (mail 12)"},{"nom":"Sarah Benmoussa","poste":"Consultante PMO","date":"J15","etat":"Premier jour sans poste (mail 12)"},{"nom":"Antoine Roche","poste":"Consultant cybersécurité","date":"J22","etat":"PC de secours ; habilitation et outil des temps manquants (mail 20)"}]'::jsonb),
('ident','{"collab":["Camille Rousseau","Chargée d''administration du personnel"],"manager":["Isabelle Moreau","Manager BU Data"],"hrbp":["Julien Mercier","HRBP de l''agence"],"dir":["Direction","Direction d''agence"],"futur":["Lucas Fabre","Futur employé, consultant data"]}'::jsonb),
('irr_manager','[["arrivee","L''annonce de l''arrivée est l''étape du manager : c''est elle qui déclenche le poste, les comptes, l''habilitation et le badge."],["boucle","Les annonces d''arrivée partent sans les services généraux : le badge et la place sont demandés trop tard."],["actions","Au comité où les managers sont présents, des actions sur l''intégration sont décidées sans responsable ni échéance."]]'::jsonb),
('indicateurs','{"arrivee":"Part des arrivants avec poste et accès prêts le premier jour","doc":"Questions « lequel / où est » reçues par mois","questions":"Questions reçues déjà couvertes par la FAQ","actions":"Actions reportées plus de 2 fois","boucle":"Arrivées signalées à temps aux services généraux","pieces":"Renvois de pièces par arrivée"}'::jsonb),
('confiance','[["✓","Sources lues : la boîte partagée « RH – Administration du personnel » et les comptes rendus, autorisées par Scalian. Le dossier partagé : source à confirmer."],["✕","Jamais de visios, d''enregistrements ni de tickets. Jamais les pièces administratives jointes."],["✕","Un mail confidentiel (santé, conflit, situation personnelle) est écarté sans être analysé."],["✕","Aucun irritant n''est attribué à une personne : le registre décrit des étapes du processus."],["✓","Le collaborateur et le manager concernés voient d''abord l''irritant et peuvent le contester ; le HRBP valide."],["✓","Chaque irritant est une interprétation des signaux, avec ses sources, pas une cause prouvée."]]'::jsonb),
('confiance_manager','[["✓","Les irritants du processus d''intégration dont une étape dépend du manager."],["✓","Votre avis (confirmer ou contester) est transmis au HRBP, qui décide."],["✕","Aucun nom de collègue, aucun mail individuel, aucune comparaison entre managers ou entre équipes."],["✕","Les irritants propres à l''administration du personnel restent visibles par la RH et le HRBP."]]'::jsonb),
('futur_mail','["Bienvenue Lucas ! Vous arrivez lundi : Isabelle Moreau vous accueille.","Votre poste et votre badge seront prêts à votre arrivée.","Réponses aux questions fréquentes : télétravail, mutuelle, notes de frais (lien).","Tous les documents d''accueil, dans leur version en vigueur, lisibles dès maintenant (lien).","Chaque envoi de pièces reçoit une confirmation automatique."]'::jsonb)
